": \"s5-difference-review\",\n    \"rpc\": \"CreateFundsDifferenceReview\",\n    \"method\": \"POST\",\n    \"path\": \"/internal/v1/funds-reconciliation-differences/{difference_number}/reviews\",\n    \"input\": \"FundsDifferenceReviewInput\",\n    \"output\": \"FundsDifference\",\n    \"body\": \"review\",\n    \"status\": \"201\",\n    \"audience\": \"内部运营\",\n    \"detail\": \"独立复核已处置差异，证据不全/未决时维持受限、锁额和门禁。\",\n    \"reqMsg\": \"CreateFundsDifferenceReviewReqMsg\",\n    \"rspMsg\": \"CreateFundsDifferenceReviewRspMsg\",\n    \"responseBody\": \"resource\",\n    \"query\": [],\n    \"file\": \"proto/trade/funds/v1/funds.proto\",\n    \"service\": \"InternalFundsOperationsService\",\n    \"timeout\": {\n      \"clientMs\": 10000,\n      \"serverMs\": 8000,\n      \"label\": \"资料写入\",\n      \"retry\": \"最多3次，原键原文原标签；提交未知先查主库，不盲写\"\n    },\n    \"timeoutClass\": \"write\"\n  }\n]\n",
